 public class PipelineElementInstallationService {

   public void installPipelineElement(String endpointUrl) {
+    validateEndpoint(endpointUrl);
     // existing installation logic
   }

+  private void validateEndpoint(String endpointUrl) {
+    try {
+      URI endpoint = new URI(endpointUrl);
+      String host = endpoint.getHost();
+
+      if (host == null
+          || (!"http".equalsIgnoreCase(endpoint.getScheme())
+          && !"https".equalsIgnoreCase(endpoint.getScheme()))) {
+        throw new IllegalArgumentException("Unsupported pipeline element endpoint");
+      }
