+            || address.isLoopbackAddress()
+            || address.isLinkLocalAddress()
+            || address.isSiteLocalAddress()
+            || address.isMulticastAddress()) {
+          throw new IllegalArgumentException("Pipeline element endpoint must not target a local address");
+        }
+      }
+    } catch (URISyntaxException e) {
+      throw new IllegalArgumentException("Invalid pipeline element endpoint", e);
+    } catch (java.net.UnknownHostException e) {
+      throw new IllegalArgumentException("Pipeline element endpoint host cannot be resolved", e);
+    }
+  }
 }

